def solve_nqueens_with_constraints(n, fixed):
    """Solve N-Queens with fixed queen positions using backtracking."""
    solution = [None] * n

    # Place fixed queens
    for row, col in fixed.items():
        solution[row] = col

    def is_safe(row, col):
        for r in range(n):
            if r == row:
                continue
            c = solution[r]
            if c is None:
                continue
            # Same column
            if c == col:
                return False
            # Same diagonal
            if abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row):
        if row == n:
            return True

        # Skip fixed rows
        if solution[row] is not None:
            # Verify the fixed placement is safe
            if not is_safe(row, solution[row]):
                return False
            return backtrack(row + 1)

        for col in range(n):
            if is_safe(row, col):
                solution[row] = col
                if backtrack(row + 1):
                    return True
                solution[row] = None

        return False

    if backtrack(0):
        return solution
    return None

